import{_ as e,o as t,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"架构约束、质量属性与系统边界","description":"","frontmatter":{"title":"架构约束、质量属性与系统边界","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"frontend/guide/engineering/architecture/principles-boundaries.md","filePath":"frontend/guide/engineering/architecture/principles-boundaries.md","lastUpdated":1785331851000}'),l={name:"frontend/guide/engineering/architecture/principles-boundaries.md"};function r(n,a,h,d,o,p){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="架构约束、质量属性与系统边界" tabindex="-1">架构约束、质量属性与系统边界 <a class="header-anchor" href="#架构约束、质量属性与系统边界" aria-label="Permalink to &quot;架构约束、质量属性与系统边界&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>前端架构不是目录层数、框架名称或一张漂亮的组件图，而是系统在真实约束下持续满足关键质量目标的结构性安排。相同的 Vue 3 应用，在 3 人团队与 80 人多团队、内部后台与全球公开站点、日更与季度发布下，不会得到同一套合理边界。</p><p>本篇建立架构工作的输入：约束、质量属性、系统上下文和责任边界。具体领域划分、模块依赖、数据流、评审与治理在后续文章展开；方案选型的 trade-off 归技术决策。</p><h2 id="_1-架构问题" tabindex="-1">1. 架构问题 <a class="header-anchor" href="#_1-架构问题" aria-label="Permalink to &quot;1. 架构问题&quot;">​</a></h2><h3 id="_1-1-结构性决定" tabindex="-1">1.1 结构性决定 <a class="header-anchor" href="#_1-1-结构性决定" aria-label="Permalink to &quot;1.1 结构性决定&quot;">​</a></h3><p>架构决定具有三个特征：影响多个模块或团队、改变成本较高、会长期约束后续设计。例如部署单元、认证边界、模块公开面、状态所有权和扩展协议都属于架构决定。</p><h3 id="_1-2-局部实现" tabindex="-1">1.2 局部实现 <a class="header-anchor" href="#_1-2-局部实现" aria-label="Permalink to &quot;1.2 局部实现&quot;">​</a></h3><p>函数命名、单个组件内部拆分和一次性的 CSS 写法通常是局部实现。局部问题可以通过重构快速修正，不应全部升级成架构委员会决策。</p><h3 id="_1-3-可演进约束" tabindex="-1">1.3 可演进约束 <a class="header-anchor" href="#_1-3-可演进约束" aria-label="Permalink to &quot;1.3 可演进约束&quot;">​</a></h3><p>架构既不是“永远不变”，也不是“没有规则”。合理做法是明确当前约束、允许的扩展方式、违反规则的例外流程和复查条件。</p><h2 id="_2-约束模型" tabindex="-1">2. 约束模型 <a class="header-anchor" href="#_2-约束模型" aria-label="Permalink to &quot;2. 约束模型&quot;">​</a></h2><h3 id="_2-1-业务约束" tabindex="-1">2.1 业务约束 <a class="header-anchor" href="#_2-1-业务约束" aria-label="Permalink to &quot;2.1 业务约束&quot;">​</a></h3><ul><li>核心用例和收入/运营风险；</li><li>上线时点、市场与合规要求；</li><li>数据敏感等级和审计要求；</li><li>失败时允许的降级与人工兜底。</li></ul><h3 id="_2-2-组织约束" tabindex="-1">2.2 组织约束 <a class="header-anchor" href="#_2-2-组织约束" aria-label="Permalink to &quot;2.2 组织约束&quot;">​</a></h3><ul><li>团队数量、所有权和协作边界；</li><li>技能结构、值班能力和维护预算；</li><li>仓库、发布权限与平台支持；</li><li>跨团队变更的协调成本。</li></ul><h3 id="_2-3-技术约束" tabindex="-1">2.3 技术约束 <a class="header-anchor" href="#_2-3-技术约束" aria-label="Permalink to &quot;2.3 技术约束&quot;">​</a></h3><ul><li>浏览器、设备、网络与可访问性基线；</li><li>已有框架、运行时、接口和部署环境；</li><li>bundle、性能、可用性和兼容窗口；</li><li>安全、隐私和第三方依赖限制。</li></ul><h3 id="_2-4-不确定性" tabindex="-1">2.4 不确定性 <a class="header-anchor" href="#_2-4-不确定性" aria-label="Permalink to &quot;2.4 不确定性&quot;">​</a></h3><p>未知不等于约束。把“订单量可能很大”改成可验证问题：峰值记录数、响应大小、导出耗时和失败重试方式分别是多少？无法立即回答时，记录假设、负责人、验证方法和截止时间。</p><h2 id="_3-质量属性" tabindex="-1">3. 质量属性 <a class="header-anchor" href="#_3-质量属性" aria-label="Permalink to &quot;3. 质量属性&quot;">​</a></h2><h3 id="_3-1-可修改性" tabindex="-1">3.1 可修改性 <a class="header-anchor" href="#_3-1-可修改性" aria-label="Permalink to &quot;3.1 可修改性&quot;">​</a></h3><p>衡量一次需求变化影响多少模块、团队和部署。模块多不等于可修改；如果所有模块共享全局 store、内部类型和隐式事件，修改成本仍会扩散。</p><h3 id="_3-2-性能" tabindex="-1">3.2 性能 <a class="header-anchor" href="#_3-2-性能" aria-label="Permalink to &quot;3.2 性能&quot;">​</a></h3><p>性能必须落实为指标、分位数、用户群和环境，例如“移动端 p75 INP 小于 200 ms”，而不是“页面要快”。完整预算与测量方法见性能工程分组。</p><h3 id="_3-3-可靠性" tabindex="-1">3.3 可靠性 <a class="header-anchor" href="#_3-3-可靠性" aria-label="Permalink to &quot;3.3 可靠性&quot;">​</a></h3><p>描述错误如何被发现、隔离、恢复与复盘。前端常见目标包括发布后错误率、关键流程成功率、降级能力和恢复时间。</p><h3 id="_3-4-安全与隐私" tabindex="-1">3.4 安全与隐私 <a class="header-anchor" href="#_3-4-安全与隐私" aria-label="Permalink to &quot;3.4 安全与隐私&quot;">​</a></h3><p>明确身份、数据、脚本和网络边界。安全要求不是最后加 CSP，而是影响渲染、缓存、日志、扩展和部署结构。</p><h3 id="_3-5-可测试性" tabindex="-1">3.5 可测试性 <a class="header-anchor" href="#_3-5-可测试性" aria-label="Permalink to &quot;3.5 可测试性&quot;">​</a></h3><p>系统是否能在不启动全部真实依赖的情况下验证核心规则，是否有稳定接口和可观察结果。可测试性通常来自显式依赖与纯规则，而不是测试框架本身。</p><h3 id="_3-6-可用性与可访问性" tabindex="-1">3.6 可用性与可访问性 <a class="header-anchor" href="#_3-6-可用性与可访问性" aria-label="Permalink to &quot;3.6 可用性与可访问性&quot;">​</a></h3><p>用户在加载、失败、键盘操作、缩放、弱网和辅助技术下能否完成任务。它会影响状态模型、组件契约和验收门禁。</p><h2 id="_4-质量属性场景" tabindex="-1">4. 质量属性场景 <a class="header-anchor" href="#_4-质量属性场景" aria-label="Permalink to &quot;4. 质量属性场景&quot;">​</a></h2><h3 id="_4-1-场景格式" tabindex="-1">4.1 场景格式 <a class="header-anchor" href="#_4-1-场景格式" aria-label="Permalink to &quot;4.1 场景格式&quot;">​</a></h3><p>可测试场景包含：刺激来源、刺激、环境、目标、系统响应和度量。</p><h3 id="_4-2-填写后的订单案例" tabindex="-1">4.2 填写后的订单案例 <a class="header-anchor" href="#_4-2-填写后的订单案例" aria-label="Permalink to &quot;4.2 填写后的订单案例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>刺激与环境</th><th>响应</th><th>度量</th></tr></thead><tbody><tr><td>性能</td><td>4G 网络打开 500 条订单列表</td><td>首屏展示骨架并先返回可见数据</td><td>p75 LCP &lt; 2.5 s，INP &lt; 200 ms</td></tr><tr><td>可修改性</td><td>新增“待复核”状态</td><td>只修改订单领域、筛选配置和文案</td><td>不影响结算模块；1 个团队 2 天内完成</td></tr><tr><td>可靠性</td><td>导出服务 5xx</td><td>页面保留筛选和任务记录，可重试</td><td>用户操作不丢失；错误含 request id</td></tr><tr><td>安全</td><td>普通客服访问其他租户订单</td><td>服务端拒绝，前端不缓存敏感结果</td><td>0 个跨租户成功响应；产生审计事件</td></tr><tr><td>可访问性</td><td>仅键盘执行批量导出</td><td>焦点按顺序到达并宣布任务状态</td><td>WCAG 2.2 AA 关键路径通过</td></tr></tbody></table><p>没有度量的场景不能用于验收；无法测量时至少定义可观察证据和判定人。</p><h2 id="_5-系统上下文" tabindex="-1">5. 系统上下文 <a class="header-anchor" href="#_5-系统上下文" aria-label="Permalink to &quot;5. 系统上下文&quot;">​</a></h2><h3 id="_5-1-用户与外部系统" tabindex="-1">5.1 用户与外部系统 <a class="header-anchor" href="#_5-1-用户与外部系统" aria-label="Permalink to &quot;5.1 用户与外部系统&quot;">​</a></h3><p>先画系统上下文，而不是组件树：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客服 / 运营</span></span>
<span class="line"><span>   -&gt; 订单 Web 应用</span></span>
<span class="line"><span>      -&gt; 身份服务</span></span>
<span class="line"><span>      -&gt; 订单 API</span></span>
<span class="line"><span>      -&gt; 导出任务 API</span></span>
<span class="line"><span>      -&gt; 监控与审计平台</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>上下文图回答系统与谁交互、交换什么数据、信任谁，不展开内部 Pinia store 或组件。</p><h3 id="_5-2-数据流" tabindex="-1">5.2 数据流 <a class="header-anchor" href="#_5-2-数据流" aria-label="Permalink to &quot;5.2 数据流&quot;">​</a></h3><p>标出敏感数据从输入到展示、缓存、日志和第三方的路径。仅画调用箭头而不注明数据、身份和协议，无法支持安全或可靠性评审。</p><h3 id="_5-3-部署边界" tabindex="-1">5.3 部署边界 <a class="header-anchor" href="#_5-3-部署边界" aria-label="Permalink to &quot;5.3 部署边界&quot;">​</a></h3><p>浏览器 bundle、静态 CDN、SSR/BFF、领域 API 是不同执行和发布单元。代码同仓库不等于同信任边界，微前端也不自动等于独立部署。</p><h2 id="_6-系统边界" tabindex="-1">6. 系统边界 <a class="header-anchor" href="#_6-系统边界" aria-label="Permalink to &quot;6. 系统边界&quot;">​</a></h2><h3 id="_6-1-产品边界" tabindex="-1">6.1 产品边界 <a class="header-anchor" href="#_6-1-产品边界" aria-label="Permalink to &quot;6.1 产品边界&quot;">​</a></h3><p>系统负责哪些用户能力、不负责哪些能力。例如订单 Web 应用负责查询、发起导出和展示进度，不负责定义财务结算规则。</p><h3 id="_6-2-领域边界" tabindex="-1">6.2 领域边界 <a class="header-anchor" href="#_6-2-领域边界" aria-label="Permalink to &quot;6.2 领域边界&quot;">​</a></h3><p>订单、客户、结算等业务概念各自拥有术语和规则。一个“公共 types”目录不应成为所有领域互相依赖的捷径。</p><h3 id="_6-3-前后端边界" tabindex="-1">6.3 前后端边界 <a class="header-anchor" href="#_6-3-前后端边界" aria-label="Permalink to &quot;6.3 前后端边界&quot;">​</a></h3><p>前端负责交互状态、视图模型和本地体验；服务端负责最终授权、持久化不变量和跨用户一致性。禁用按钮、路由守卫和 TypeScript 类型不能替代服务端控制。</p><h3 id="_6-4-平台与业务边界" tabindex="-1">6.4 平台与业务边界 <a class="header-anchor" href="#_6-4-平台与业务边界" aria-label="Permalink to &quot;6.4 平台与业务边界&quot;">​</a></h3><p>平台提供构建、鉴权接入、观测 SDK、设计系统等可复用能力；业务模块拥有订单状态、审批规则和页面流程。平台不应吸收所有业务差异成为“超级框架”。</p><h3 id="_6-5-第三方边界" tabindex="-1">6.5 第三方边界 <a class="header-anchor" href="#_6-5-第三方边界" aria-label="Permalink to &quot;6.5 第三方边界&quot;">​</a></h3><p>第三方 SDK、iframe、支付和地图服务需要适配层，限制数据、权限、失败和升级影响。业务代码不要散落供应商 API。</p><h2 id="_7-边界产物" tabindex="-1">7. 边界产物 <a class="header-anchor" href="#_7-边界产物" aria-label="Permalink to &quot;7. 边界产物&quot;">​</a></h2><h3 id="_7-1-责任表" tabindex="-1">7.1 责任表 <a class="header-anchor" href="#_7-1-责任表" aria-label="Permalink to &quot;7.1 责任表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>主负责人</th><th>输入</th><th>输出</th><th>不负责</th></tr></thead><tbody><tr><td>订单查询模块</td><td>订单前端团队</td><td>已验证查询条件</td><td>订单 view model</td><td>最终数据授权</td></tr><tr><td>BFF</td><td>Web 平台团队</td><td>session、页面查询</td><td>聚合 API</td><td>订单领域事务</td></tr><tr><td>订单 API</td><td>订单后端团队</td><td>主体、资源命令</td><td>领域结果</td><td>页面交互状态</td></tr><tr><td>设计系统</td><td>UI 平台团队</td><td>token、通用交互</td><td>可访问组件</td><td>业务审批流程</td></tr></tbody></table><h3 id="_7-2-依赖清单" tabindex="-1">7.2 依赖清单 <a class="header-anchor" href="#_7-2-依赖清单" aria-label="Permalink to &quot;7.2 依赖清单&quot;">​</a></h3><p>每个外部依赖记录 owner、SLO/限制、认证方式、超时、错误语义、降级和联系人。只写“依赖订单接口”无法指导故障处理。</p><h3 id="_7-3-假设与风险" tabindex="-1">7.3 假设与风险 <a class="header-anchor" href="#_7-3-假设与风险" aria-label="Permalink to &quot;7.3 假设与风险&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 假设：单次查询最多返回 500 条摘要。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 验证：生产响应大小 p99 与接口上限测试。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 负责人：订单 API 团队。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 截止：方案评审前。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 风险：导出任务在灰度期间存在新旧状态枚举。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 控制：前端 unknown fallback；契约测试覆盖兼容窗口。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="_8-架构约束" tabindex="-1">8. 架构约束 <a class="header-anchor" href="#_8-架构约束" aria-label="Permalink to &quot;8. 架构约束&quot;">​</a></h2><h3 id="_8-1-必须自动化的约束" tabindex="-1">8.1 必须自动化的约束 <a class="header-anchor" href="#_8-1-必须自动化的约束" aria-label="Permalink to &quot;8.1 必须自动化的约束&quot;">​</a></h3><ul><li>领域模块只能通过公开入口依赖；</li><li>浏览器代码不能导入 server-only 模块；</li><li>敏感接口响应不进入共享缓存；</li><li>核心 bundle 和性能指标不超过预算；</li><li>发布制品必须携带版本并上传 Source Map。</li></ul><p>能静态检查的约束应进入 lint、依赖图、测试或 CI；只写在文档中会逐渐失效。</p><h3 id="_8-2-需要评审的约束" tabindex="-1">8.2 需要评审的约束 <a class="header-anchor" href="#_8-2-需要评审的约束" aria-label="Permalink to &quot;8.2 需要评审的约束&quot;">​</a></h3><p>数据所有权、跨团队 API、部署单元和隐私边界无法只靠 lint 判断，需要图、数据和负责人共同评审。</p><h3 id="_8-3-临时例外" tabindex="-1">8.3 临时例外 <a class="header-anchor" href="#_8-3-临时例外" aria-label="Permalink to &quot;8.3 临时例外&quot;">​</a></h3><p>例外记录原因、影响、owner、到期和移除条件：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">no-cross-domain-import</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">exception</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">legacy-order-export -&gt; customer/format-name</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">order-platform</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">expires</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2026-10-01</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">removal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">migrate to customer public adapter</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>没有期限与 owner 的例外会成为永久架构。</p><h2 id="_9-常见误区" tabindex="-1">9. 常见误区 <a class="header-anchor" href="#_9-常见误区" aria-label="Permalink to &quot;9. 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>问题</th></tr></thead><tbody><tr><td>先选微前端再找理由</td><td>方案先于约束和质量目标</td></tr><tr><td>按页面截图划模块</td><td>页面变化会让领域职责持续漂移</td></tr><tr><td>共享目录解决重复</td><td>隐藏所有权，形成高耦合公共层</td></tr><tr><td>“高性能、可扩展”</td><td>没有场景、指标和负载边界</td></tr><tr><td>前端校验保证安全</td><td>客户端可绕过，无法维护服务端不变量</td></tr><tr><td>文档写了就算治理</td><td>约束没有自动化、owner 和例外机制</td></tr></tbody></table><h2 id="_10-评审检查" tabindex="-1">10. 评审检查 <a class="header-anchor" href="#_10-评审检查" aria-label="Permalink to &quot;10. 评审检查&quot;">​</a></h2><ul><li>关键用户与外部系统是否完整；</li><li>每项质量属性是否有场景和度量；</li><li>数据、身份、部署和团队边界是否一致或明确不一致；</li><li>每个关键依赖是否有 owner、失败和降级定义；</li><li>约束是否能被代码、测试、监控或评审验证；</li><li>假设和例外是否有负责人、期限与复查条件。</li></ul><h2 id="_11-总结" tabindex="-1">11. 总结 <a class="header-anchor" href="#_11-总结" aria-label="Permalink to &quot;11. 总结&quot;">​</a></h2><ul><li>架构由高影响、难逆转的结构性决定组成，目标是满足明确质量属性。</li><li>业务、组织、技术约束与不确定性是架构输入，工具和框架不是起点。</li><li>质量属性必须写成带环境、响应和度量的可验证场景。</li><li>系统上下文和责任边界先于内部目录，边界需要同时说明负责与不负责什么。</li><li>约束通过自动化、评审、owner 和有期限例外持续生效。</li></ul><h2 id="_12-参考资料" tabindex="-1">12. 参考资料 <a class="header-anchor" href="#_12-参考资料" aria-label="Permalink to &quot;12. 参考资料&quot;">​</a></h2><ul><li><a href="https://c4model.com/" target="_blank" rel="noreferrer">C4 Model</a></li><li><a href="https://docs.aws.amazon.com/wellarchitected/latest/framework/the-pillars-of-the-framework.html" target="_blank" rel="noreferrer">AWS：Architecture quality attributes</a></li><li><a href="https://owasp.org/www-community/Threat_Modeling" target="_blank" rel="noreferrer">OWASP：Threat Modeling</a></li><li><a href="https://martinfowler.com/ieeeSoftware/whoNeedsArchitect.pdf" target="_blank" rel="noreferrer">Martin Fowler：Who Needs an Architect?</a></li></ul>`,84)])])}const b=e(l,[["render",r]]);export{u as __pageData,b as default};
